//! Checks the `smoothBoundaries` chain against QuPath's, one stage at a time.
//!
//! Fixture generated by `parity/java/SmoothBoundaries.java` via
//! `./parity/record.sh`, recorded through `WatershedCellDetection`'s lines
//! 925-933 — the four stages between the traced outline and the polygon a
//! `PathObject` carries. Needs no slide.
//!
//! The successor of `parity_wand_outline.rs`, which pins the ring going *in*.
//! `DIVERGENCES.md` D-008 is why this exists: QuPath's seam resolution compares
//! `geometry.getArea()` of the polygon this chain produces, which is neither the
//! enclosed pixel count nor the traced ring's own area.
//!
//! # Every stage is compared, not only the result
//!
//! Stage three's interpolation interval is `min(2, n * 0.1)` over the count
//! **stage two** produced, so a stage two of the right shape and the wrong
//! length silently respaces everything after it and can still land near the
//! recorded end. Comparing the intermediates is what makes such a port fail at
//! the stage that is wrong. The interval itself is compared for the same reason.
//!
//! # Two downsamples, because one of them is the identity
//!
//! `simplifyPolygon`'s threshold is `sqrt(downsample) / 2` while
//! `convertToPolygonROI` scales the coordinates by `downsample`, so the polygon
//! grows faster than the tolerance and a **coarser** downsample simplifies
//! **less** — `ell` keeps 3 points at 1.0 and 7 at 4.0. At downsample 1.0 the
//! scaling stage is the identity and that interaction is invisible, which is
//! exactly the shape of bug this project has hit before.
//!
//! # Tolerance
//!
//! Compared as floats, not bit-exactly. The chain crosses `f32` and `f64`
//! several times and its walk goes through `atan2`/`cos`/`sin`, whose last bits
//! are not guaranteed identical between libm implementations. The bound below is
//! tight enough that a wrong *algorithm* cannot pass it — every divergence found
//! while writing the port was a whole point out of place or a different point
//! count, never a low bit — and the point counts are compared exactly, which is
//! the check that actually has teeth.

use qupath_watershed::smooth_boundary;

const FIXTURE: &str = include_str!("../../../parity/fixtures/SmoothBoundaries.json");

/// Absolute coordinate tolerance. See the module comment: this guards against
/// libm's last bits, not against a different walk.
const TOLERANCE: f64 = 1e-4;

/// One `{ ... }` case block, in file order.
fn cases(fixture: &str) -> Vec<&str> {
    fixture
        .split("\n    {\n")
        .skip(1)
        .map(|block| block.split("\n    }").next().expect("a case block"))
        .collect()
}

/// The text of one field.
fn text<'a>(block: &'a str, key: &str) -> &'a str {
    let needle = format!("\"{key}\": ");
    let at = block
        .find(&needle)
        .unwrap_or_else(|| panic!("no {key} in {block}"))
        + needle.len();
    let rest = &block[at..];
    if let Some(body) = rest.strip_prefix('"') {
        let end = body.find('"').expect("an unterminated string");
        return &body[..end];
    }
    let end = rest.find([',', '\n']).unwrap_or(rest.len());
    rest[..end].trim()
}

fn float(block: &str, key: &str) -> f64 {
    text(block, key).parse().expect("a number")
}

fn integer(block: &str, key: &str) -> usize {
    text(block, key).parse().expect("an integer")
}

/// The `mask` array, as bytes.
fn mask(block: &str) -> Vec<u8> {
    let needle = "\"mask\": [";
    let open = block.find(needle).expect(needle) + needle.len();
    let close = block[open..].find(']').expect("an unterminated mask") + open;
    block[open..close]
        .split(',')
        .map(|value| value.trim().parse::<u8>().expect("a 0 or 1"))
        .collect()
}

/// A `[[x, y], ...]` array named `key`.
fn points(block: &str, key: &str) -> Vec<(f64, f64)> {
    let needle = format!("\"{key}\": [");
    let open = block.find(&needle).expect(&needle) + needle.len();
    // The outer array's close, which is the first `]` not closing a pair.
    let mut depth = 1_usize;
    let mut close = open;
    for (offset, ch) in block[open..].char_indices() {
        match ch {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 {
                    close = open + offset;
                    break;
                }
            }
            _ => {}
        }
    }
    let body = &block[open..close];
    if body.trim().is_empty() {
        return Vec::new();
    }
    body.split("], [")
        .map(|pair| {
            let pair = pair.trim().trim_start_matches('[').trim_end_matches(']');
            let (x, y) = pair.split_once(',').expect("an [x, y] pair");
            (
                x.trim().parse().expect("a number"),
                y.trim().parse().expect("a number"),
            )
        })
        .collect()
}

/// Asserts two point lists match, reporting the first index that does not.
fn assert_points(ours: &[(f64, f64)], theirs: &[(f64, f64)], case: &str, stage: &str) {
    assert_eq!(
        ours.len(),
        theirs.len(),
        "{case}/{stage}: {} points, QuPath has {}\n  ours:   {ours:?}\n  theirs: {theirs:?}",
        ours.len(),
        theirs.len()
    );
    for (index, (&(ox, oy), &(tx, ty))) in ours.iter().zip(theirs).enumerate() {
        assert!(
            (ox - tx).abs() <= TOLERANCE && (oy - ty).abs() <= TOLERANCE,
            "{case}/{stage}: point {index} is ({ox}, {oy}), QuPath has ({tx}, {ty})"
        );
    }
}

/// The outline the chain starts from, as the recorder took it: the first region
/// in scan order.
///
/// Read from the fixture's own `outline` field rather than re-traced through
/// `outline_mask`, so a failure here is a smoothing failure. The trace is
/// `parity_wand_outline.rs`'s subject and is pinned there; a test that failed
/// for either reason would point at the wrong file.
fn starting_outline(block: &str) -> Vec<(f64, f64)> {
    points(block, "outline")
}

#[test]
fn every_stage_matches_qupath() {
    let blocks = cases(FIXTURE);
    assert!(!blocks.is_empty(), "the fixture has no cases");

    for block in &blocks {
        let name = text(block, "name");
        let downsample = float(block, "downsample");
        let case = format!("{name}@{downsample}");

        let stages = smooth_boundary(&starting_outline(block), downsample);

        assert_points(
            &stages.interpolated,
            &points(block, "interpolated"),
            &case,
            "interpolated",
        );
        assert_points(
            &stages.smoothed,
            &points(block, "smoothed"),
            &case,
            "smoothed",
        );

        let interval = float(block, "reinterpolate_interval");
        assert!(
            (stages.reinterpolate_interval - interval).abs() <= TOLERANCE,
            "{case}: interval {}, QuPath has {interval} — see the module comment \
             on why this is compared rather than inferred",
            stages.reinterpolate_interval
        );

        assert_points(
            &stages.reinterpolated,
            &points(block, "reinterpolated"),
            &case,
            "reinterpolated",
        );
        assert_points(&stages.scaled, &points(block, "scaled"), &case, "scaled");
        assert_points(
            &stages.simplified,
            &points(block, "simplified"),
            &case,
            "simplified",
        );
    }
}

/// The traced outline this chain consumes is the one the mask actually has.
///
/// Guards the fixture rather than the port: `SmoothBoundaries.json` records its
/// own starting outline, and if that ever stopped agreeing with what
/// `outline_mask` traces, `every_stage_matches_qupath` would be checking the
/// smoothing of a shape this pipeline never produces — and would still pass.
#[test]
fn the_recorded_outline_is_the_one_we_trace() {
    for block in &cases(FIXTURE) {
        let name = text(block, "name");
        let width = integer(block, "width");
        let traced = qupath_watershed::outline_mask(&mask(block), width);
        assert!(!traced.is_empty(), "{name}: nothing traced");

        let recorded = starting_outline(block);
        let ours: Vec<(f64, f64)> = traced[0]
            .points
            .iter()
            .map(|&(x, y)| (f64::from(x), f64::from(y)))
            .collect();

        // Up to rotation, for the reason `parity_wand_outline.rs` gives at
        // length: ImageJ's listing offset is not reproduced, and the fixture
        // records ImageJ's.
        assert_eq!(
            ours.len(),
            recorded.len(),
            "{name}: {} vertices, recorded {}",
            ours.len(),
            recorded.len()
        );
        let matches = (0..ours.len())
            .any(|offset| (0..ours.len()).all(|i| ours[(offset + i) % ours.len()] == recorded[i]));
        assert!(matches, "{name}: traced {ours:?}, recorded {recorded:?}");
    }
}
